import printSizesData from "./print-sizes.json";
import { SIZES, type SizeKey } from "./products";

const printSizes = printSizesData as Record<string, string[]>;

// Returns the SIZES this specific image is allowed to be sold at, based on
// lib/print-sizes.json (generated by scripts/check-print-sizes.mjs from each
// image's real resolution). If an image has no entry yet, every size is
// allowed, so nothing breaks before the check script has been run.
export function getAvailableSizes(imageFile: string) {
  const allowedKeys = printSizes[imageFile];
  if (!allowedKeys) return SIZES;
  return SIZES.filter((s) => allowedKeys.includes(s.key as SizeKey));
}